# This function calculates the percentage of night shifts for a given month and year
def calculate_night_shift_percentage(year, month, night_shifts):
    total_days = days_in_month(year, month)
    night_shift_count = 0
    for day in range(1, total_days + 1):
        if is_night_shift(year, month, day):
            night_shift_count += 1
    if total_days == 0:
        return 0
    percentage = night_shift_count / total_days
    return percentage

